-- Frozen real Room V2 DDL from unchanged schema 2; never obtained by relabelling V3.
CREATE TABLE IF NOT EXISTS `entity_identities` (`uuid` TEXT NOT NULL, `kind` TEXT NOT NULL, PRIMARY KEY(`uuid`))
CREATE TABLE IF NOT EXISTS `target_profiles` (`uuid` TEXT NOT NULL, `name` TEXT NOT NULL, `discipline` TEXT NOT NULL, `diameterCm` INTEGER NOT NULL, `maxScore` INTEGER NOT NULL, `minScore` INTEGER NOT NULL, `defaultArrowCount` INTEGER NOT NULL, `defaultDistanceM` INTEGER NOT NULL, `isBuiltIn` INTEGER NOT NULL, `xRingEnabled` INTEGER NOT NULL, `xRingLabel` TEXT NOT NULL, `innerTenRadiusBits` INTEGER NOT NULL, `regulatoryEdition` TEXT, `zoneCount` INTEGER NOT NULL, PRIMARY KEY(`uuid`), FOREIGN KEY(`uuid`) REFERENCES `entity_identities`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT )
CREATE TABLE IF NOT EXISTS `target_zones` (`profileUuid` TEXT NOT NULL, `position` INTEGER NOT NULL, `score` INTEGER NOT NULL, `innerRadiusBits` INTEGER NOT NULL, `outerRadiusBits` INTEGER NOT NULL, `colorName` TEXT NOT NULL, `colorHex` TEXT, PRIMARY KEY(`profileUuid`, `position`), FOREIGN KEY(`profileUuid`) REFERENCES `target_profiles`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT )
CREATE UNIQUE INDEX IF NOT EXISTS `index_target_zones_profileUuid_score` ON `target_zones` (`profileUuid`, `score`)
CREATE TABLE IF NOT EXISTS `sessions` (`uuid` TEXT NOT NULL, `profileUuid` TEXT NOT NULL, `archiveSchemaVersion` INTEGER NOT NULL, `scoringContractVersion` INTEGER NOT NULL, `localDateTime` TEXT NOT NULL, `zoneId` TEXT NOT NULL, `offset` TEXT NOT NULL, `status` TEXT NOT NULL, `plannedEndCount` INTEGER, `title` TEXT NOT NULL, `distanceM` INTEGER NOT NULL, `arrowCountMode` TEXT NOT NULL, `arrowCountPerEnd` INTEGER, `isIndoor` INTEGER NOT NULL, `scoringMode` TEXT NOT NULL, `bowUuid` TEXT, `arrowSetUuid` TEXT, `locationName` TEXT, `notes` TEXT, `endCount` INTEGER NOT NULL, `started_epochSecond` INTEGER, `started_nano` INTEGER, `ended_epochSecond` INTEGER, `ended_nano` INTEGER, `created_epochSecond` INTEGER, `created_nano` INTEGER, `updated_epochSecond` INTEGER, `updated_nano` INTEGER, PRIMARY KEY(`uuid`), FOREIGN KEY(`uuid`) REFERENCES `entity_identities`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT , FOREIGN KEY(`profileUuid`) REFERENCES `target_profiles`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT )
CREATE INDEX IF NOT EXISTS `index_sessions_profileUuid` ON `sessions` (`profileUuid`)
CREATE TABLE IF NOT EXISTS `ends` (`uuid` TEXT NOT NULL, `sessionUuid` TEXT NOT NULL, `position` INTEGER NOT NULL, `index` INTEGER NOT NULL, `status` TEXT NOT NULL, `notes` TEXT, `impactCount` INTEGER NOT NULL, `created_epochSecond` INTEGER, `created_nano` INTEGER, `updated_epochSecond` INTEGER, `updated_nano` INTEGER, `validated_epochSecond` INTEGER, `validated_nano` INTEGER, PRIMARY KEY(`uuid`), FOREIGN KEY(`uuid`) REFERENCES `entity_identities`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT , FOREIGN KEY(`sessionUuid`) REFERENCES `sessions`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT )
CREATE UNIQUE INDEX IF NOT EXISTS `index_ends_sessionUuid_position` ON `ends` (`sessionUuid`, `position`)
CREATE UNIQUE INDEX IF NOT EXISTS `index_ends_sessionUuid_index` ON `ends` (`sessionUuid`, `index`)
CREATE TABLE IF NOT EXISTS `impacts` (`uuid` TEXT NOT NULL, `endUuid` TEXT NOT NULL, `profileUuid` TEXT NOT NULL, `position` INTEGER NOT NULL, `index` INTEGER NOT NULL, `xBits` INTEGER NOT NULL, `yBits` INTEGER NOT NULL, `inputMode` TEXT NOT NULL, `note` TEXT, `repositionCount` INTEGER NOT NULL, `created_epochSecond` INTEGER, `created_nano` INTEGER, `updated_epochSecond` INTEGER, `updated_nano` INTEGER, PRIMARY KEY(`uuid`), FOREIGN KEY(`uuid`) REFERENCES `entity_identities`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT , FOREIGN KEY(`endUuid`) REFERENCES `ends`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT , FOREIGN KEY(`profileUuid`) REFERENCES `target_profiles`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT )
CREATE UNIQUE INDEX IF NOT EXISTS `index_impacts_endUuid_position` ON `impacts` (`endUuid`, `position`)
CREATE UNIQUE INDEX IF NOT EXISTS `index_impacts_endUuid_index` ON `impacts` (`endUuid`, `index`)
CREATE INDEX IF NOT EXISTS `index_impacts_profileUuid` ON `impacts` (`profileUuid`)
CREATE TABLE IF NOT EXISTS `score_decisions` (`impactUuid` TEXT NOT NULL, `revision` INTEGER NOT NULL, `kind` TEXT NOT NULL, `selectedScore` INTEGER NOT NULL, `selectedIsX` INTEGER NOT NULL, `boundaryType` TEXT, `boundaryRadiusBits` INTEGER, `reason` TEXT, `decided_epochSecond` INTEGER, `decided_nano` INTEGER, `assertions_distanceBits` INTEGER NOT NULL, `assertions_calculated` INTEGER NOT NULL, `assertions_final` INTEGER NOT NULL, `assertions_geometricIsX` INTEGER NOT NULL, `assertions_isX` INTEGER NOT NULL, `assertions_isMiss` INTEGER NOT NULL, `assertions_isCordDecisionManual` INTEGER NOT NULL, PRIMARY KEY(`impactUuid`, `revision`), FOREIGN KEY(`impactUuid`) REFERENCES `impacts`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT )
CREATE TABLE IF NOT EXISTS `impact_repositions` (`impactUuid` TEXT NOT NULL, `sequence` INTEGER NOT NULL, `inputMode` TEXT NOT NULL, `previousXBits` INTEGER NOT NULL, `previousYBits` INTEGER NOT NULL, `newXBits` INTEGER NOT NULL, `newYBits` INTEGER NOT NULL, `reason` TEXT, `impactCreated_epochSecond` INTEGER, `impactCreated_nano` INTEGER, `previousUpdated_epochSecond` INTEGER, `previousUpdated_nano` INTEGER, `changed_epochSecond` INTEGER, `changed_nano` INTEGER, PRIMARY KEY(`impactUuid`, `sequence`), FOREIGN KEY(`impactUuid`) REFERENCES `impacts`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT , FOREIGN KEY(`impactUuid`, `sequence`) REFERENCES `score_decisions`(`impactUuid`, `revision`) ON UPDATE NO ACTION ON DELETE RESTRICT )
CREATE TABLE IF NOT EXISTS `bows` (`uuid` TEXT NOT NULL, `name` TEXT NOT NULL, `type` TEXT, `drawWeightLbsBits` INTEGER, `brand` TEXT, `model` TEXT, `notes` TEXT, `created_epochSecond` INTEGER, `created_nano` INTEGER, `updated_epochSecond` INTEGER, `updated_nano` INTEGER, PRIMARY KEY(`uuid`), FOREIGN KEY(`uuid`) REFERENCES `entity_identities`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT )
CREATE TABLE IF NOT EXISTS `arrow_sets` (`uuid` TEXT NOT NULL, `name` TEXT NOT NULL, `spine` TEXT, `length` TEXT, `pointWeight` TEXT, `nock` TEXT, `vanes` TEXT, `material` TEXT, `notes` TEXT, `created_epochSecond` INTEGER, `created_nano` INTEGER, `updated_epochSecond` INTEGER, `updated_nano` INTEGER, PRIMARY KEY(`uuid`), FOREIGN KEY(`uuid`) REFERENCES `entity_identities`(`uuid`) ON UPDATE NO ACTION ON DELETE RESTRICT )
CREATE TABLE room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT)
